"""Proxyshop offline helper for Nightvault.

Installs a small plugin into Proxyshop (the free program that fills Photoshop card templates) so it reads Magic card
data from the Scryfall card file Nightvault keeps on this PC, instead of asking scryfall.com for every card.
Cards that are not in the file can still come from the internet (when allowed) and are remembered for next time.
"""
import json
import os
from pathlib import Path

VERSION = "1.0.0"
FILES = {
 "manifest.yml": "###\n# * Plugin Details\n###\n\nPLUGIN:\n  name: 'Nightvault Offline'\n  author: 'Nightvault'\n  desc: \"Card data without internet: Proxyshop reads Magic cards from the Scryfall card file Nightvault keeps on your PC. No templates - it works with all of them.\"\n  license: 'MPL-2.0'\n  requires: '^1.13.0'\n  version: '1.0.0'\n",
 "py/__init__.py": "\"\"\"\nNightvault Offline - lets Proxyshop work without internet.\n\nProxyshop normally asks the Scryfall website for every card it renders. This plugin answers those questions from the\nScryfall card file on your own PC first (default_cards.json - the file Nightvault already downloads for its Magic card\nhub), and only goes online for cards that are not in it (and remembers those, so next time they work offline too).\n\nWhere the card file is:\n  1. \"bulk\" in settings.json next to this plugin (Nightvault fills this in when you click \"Set up Proxyshop\"), or\n  2. a default_cards.json placed in this plugin's \"data\" folder.\nThe first time (and after the card file changes) a small index is made in \"data\" - that takes a minute.\n\"\"\"\nimport json\nimport os\nimport re\nimport threading\nimport time\nimport unicodedata\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parent.parent\nDATA = ROOT / 'data'\nDATA.mkdir(exist_ok=True)\nEXTRA = DATA / 'extra_cards.jsonl'          # cards fetched online, kept for next time\nINDEX = DATA / 'index.json'\n_lock = threading.RLock()\n_ready = threading.Event()\n_st = {'idx': None, 'bulk': None, 'error': None}\n\n\ndef _say(msg):\n    try:\n        from src import CONSOLE\n        CONSOLE.update(f'[Nightvault Offline] {msg}')\n    except Exception:\n        print(f'[Nightvault Offline] {msg}')\n\n\ndef _settings():\n    try:\n        with open(ROOT / 'settings.json', encoding='utf-8') as f:\n            return json.load(f)\n    except Exception:\n        return {}\n\n\ndef _norm(s):\n    s = unicodedata.normalize('NFKD', str(s or '')).encode('ascii', 'ignore').decode().lower()\n    return re.sub(r'[^a-z0-9]+', ' ', s).strip()\n\n\ndef _bulk_path():\n    p = (_settings().get('bulk') or '').strip().strip('\"')\n    for c in [p, str(DATA / 'default_cards.json'), str(DATA / 'all_cards.json')]:\n        if c and os.path.isfile(c):\n            return c\n    return None\n\n\ndef _add(idx, src, off, c):\n    ref = [src, off]\n    cid = c.get('id')\n    if cid:\n        idx['id'][cid] = ref\n    lang = c.get('lang', 'en')\n    if c.get('set') and c.get('collector_number'):\n        idx['sn'][f\"{c['set'].lower()}|{c['collector_number'].lower()}|{lang}\"] = ref\n    names = {_norm(c.get('name'))}\n    for f in c.get('card_faces') or []:\n        names.add(_norm(f.get('name')))\n    if c.get('printed_name'):\n        names.add(_norm(c.get('printed_name')))\n    for n in names:\n        if n:\n            idx['name'].setdefault(n, []).append(ref)\n    if c.get('oracle_id'):\n        idx['oracle'].setdefault(c['oracle_id'], []).append(ref)\n\n\ndef _scan(path, src, idx):\n    \"\"\"Index a file with one card object per line (Scryfall bulk files and our extra file look like that).\"\"\"\n    n = 0\n    with open(path, 'rb') as f:\n        off = 0\n        for line in f:\n            s = line.strip()\n            if s.endswith(b','):\n                s = s[:-1]\n            if s.startswith(b'{') and s.endswith(b'}'):\n                try:\n                    c = json.loads(s)\n                    if c.get('object') == 'card':\n                        _add(idx, src, off, c)\n                        n += 1\n                except Exception:\n                    pass\n            off += len(line)\n    return n\n\n\ndef _build():\n    try:\n        bulk = _bulk_path()\n        if not bulk:\n            _st['error'] = 'no card file - set \"bulk\" in settings.json (Nightvault does this for you)'\n            _say('No offline card file yet: ' + _st['error'])\n            return\n        st = os.stat(bulk)\n        sig = f'{bulk}|{st.st_size}|{int(st.st_mtime)}|1'\n        idx = None\n        if INDEX.is_file():\n            try:\n                with open(INDEX, encoding='utf-8') as f:\n                    idx = json.load(f)\n                if idx.get('sig') != sig:\n                    idx = None\n            except Exception:\n                idx = None\n        if idx is None:\n            _say('Making the offline card index (one time, about a minute) ...')\n            t = time.time()\n            idx = {'sig': sig, 'id': {}, 'sn': {}, 'name': {}, 'oracle': {}}\n            n = _scan(bulk, 'bulk', idx)\n            tmp = INDEX.with_suffix('.tmp')\n            with open(tmp, 'w', encoding='utf-8') as f:\n                json.dump(idx, f, separators=(',', ':'))\n            os.replace(tmp, INDEX)\n            _say(f'Offline card index ready: {n:,} cards in {time.time() - t:.0f} s')\n        if EXTRA.is_file():\n            _scan(EXTRA, 'extra', idx)\n        _st['idx'], _st['bulk'] = idx, bulk\n    except Exception as e:\n        _st['error'] = str(e)\n        _say(f'Could not read the offline card file: {e}')\n    finally:\n        _ready.set()\n\n\ndef _load(ref):\n    path = _st['bulk'] if ref[0] == 'bulk' else str(EXTRA)\n    with open(path, 'rb') as f:\n        f.seek(ref[1])\n        s = f.readline().strip()\n    if s.endswith(b','):\n        s = s[:-1]\n    return json.loads(s)\n\n\ndef _remember(card):\n    \"\"\"A card that had to come from the internet: keep it for next time.\"\"\"\n    try:\n        if not isinstance(card, dict) or card.get('object') != 'card':\n            return\n        with _lock:\n            idx = _st['idx']\n            if idx is None:\n                return\n            if card.get('id') in idx['id']:\n                return\n            with open(EXTRA, 'ab') as f:\n                off = f.tell()\n                f.write(json.dumps(card, separators=(',', ':')).encode('utf-8') + b'\\n')\n            _add(idx, 'extra', off, card)\n    except Exception:\n        pass\n\n\ndef _idx():\n    _ready.wait(600)\n    return _st['idx']\n\n\ndef _online():\n    return bool(_settings().get('online_fallback', True))\n\n\nEXTRAS_LAYOUTS = {'token', 'double_faced_token', 'emblem', 'art_series', 'vanguard', 'planar', 'scheme'}\n\n\ndef _install():\n    from src.utils import scryfall as S\n    orig = {k: getattr(S, k) for k in ('get_card_unique', 'get_card_search', 'get_cards_oracle', 'get_uri_object', 'get_set')}\n\n    def get_card_unique(card_set, card_number, lang='en'):\n        idx = _idx()\n        if idx:\n            ref = idx['sn'].get(f'{str(card_set).lower()}|{str(card_number).lower()}|{lang}')\n            if ref:\n                c = _load(ref)\n                if S.is_playable_card(c):\n                    return c\n        if not _online():\n            raise S.ScryfallException(exception=S.RequestException('Not in the offline card file (and going online is off).'),\n                                      card_set=card_set, card_number=card_number, lang=lang)\n        c = orig['get_card_unique'](card_set, card_number, lang=lang)\n        _remember(c)\n        return c\n\n    def get_card_search(card_name, card_set=None, lang='en', **kwargs):\n        idx = _idx()\n        if idx:\n            refs = idx['name'].get(_norm(card_name), [])\n            cards = []\n            for ref in refs:\n                try:\n                    c = _load(ref)\n                except Exception:\n                    continue\n                if c.get('lang', 'en') != lang or not S.is_playable_card(c):\n                    continue\n                if card_set and c.get('set', '').lower() != str(card_set).lower():\n                    continue\n                if str(kwargs.get('include_extras', 'False')).lower() != 'true' and (c.get('layout') in EXTRAS_LAYOUTS or c.get('set_type') in ('token', 'memorabilia')):\n                    continue\n                cards.append(c)\n            if cards:\n                order = str(kwargs.get('order', 'released')).lower()\n                key = {'set': lambda c: c.get('set', ''), 'name': lambda c: c.get('name', ''), 'rarity': lambda c: c.get('rarity', ''),\n                       'artist': lambda c: c.get('artist', ''), 'cmc': lambda c: c.get('cmc', 0)}.get(order, lambda c: c.get('released_at', ''))\n                cards.sort(key=key, reverse=str(kwargs.get('dir', 'desc')).lower() != 'asc')\n                return cards[0]\n        if not _online():\n            return S.ScryfallException(exception=S.RequestException('Not in the offline card file (and going online is off).'),\n                                       name=card_name, code=card_set, lang=lang)\n        c = orig['get_card_search'](card_name, card_set=card_set, lang=lang, **kwargs)\n        _remember(c)\n        return c\n\n    def get_cards_oracle(oracle_id, all_pages=False, **kwargs):\n        idx = _idx()\n        if idx and oracle_id in idx['oracle']:\n            out = []\n            for ref in idx['oracle'][oracle_id]:\n                try:\n                    out.append(_load(ref))\n                except Exception:\n                    pass\n            out.sort(key=lambda c: c.get('released_at', ''), reverse=str(kwargs.get('dir', 'asc')).lower() == 'desc')\n            return out\n        return orig['get_cards_oracle'](oracle_id, all_pages=all_pages, **kwargs) if _online() else []\n\n    def get_uri_object(url, **kwargs):\n        m = re.search(r'/cards/([0-9a-f-]{36})', str(url))\n        idx = _idx()\n        if m and idx and m.group(1) in idx['id']:\n            return _load(idx['id'][m.group(1)])\n        if not _online():\n            return {}\n        c = orig['get_uri_object'](url, **kwargs)\n        _remember(c)\n        return c\n\n    def get_set(card_set):\n        idx = _idx()\n        if idx:                                      # set details from any card of that set\n            for k, ref in idx['sn'].items():\n                if k.startswith(str(card_set).lower() + '|'):\n                    c = _load(ref)\n                    return {'object': 'set', 'code': c.get('set'), 'name': c.get('set_name'), 'set_type': c.get('set_type'),\n                            'released_at': c.get('released_at'), 'icon_svg_uri': '', 'id': c.get('set_id')}\n        return orig['get_set'](card_set) if _online() else {}\n\n    for k, fn in dict(get_card_unique=get_card_unique, get_card_search=get_card_search, get_cards_oracle=get_cards_oracle,\n                      get_uri_object=get_uri_object, get_set=get_set).items():\n        setattr(S, k, fn)\n    # modules that copied a function at import time\n    import sys\n    for mod in ('src.layouts', 'src.cards', 'src.templates._core'):\n        m = sys.modules.get(mod)\n        if m:\n            for k in ('get_cards_oracle', 'get_card_unique', 'get_card_search', 'get_uri_object', 'get_set'):\n                if hasattr(m, k):\n                    setattr(m, k, getattr(S, k))\n\n\ntry:\n    _install()\n    threading.Thread(target=_build, name='nightvault-offline-index', daemon=True).start()\nexcept Exception as _e:\n    print(f'[Nightvault Offline] not active: {_e}')\n"
}


def find_proxyshop(path):
    """The Proxyshop folder (the one with Proxyshop.exe or main.py and a 'plugins' or 'templates' folder), or None."""
    p = Path(str(path or "").strip().strip('"'))
    for c in [p, p.parent]:
        if c.is_dir() and ((c / "plugins").is_dir() or (c / "templates").is_dir()) and \
                any((c / n).exists() for n in ("Proxyshop.exe", "main.py", "plugins", "src")):
            return c
    return None


def status(path):
    root = find_proxyshop(path)
    if not root:
        return {"found": False}
    plug = root / "plugins" / "NightvaultOffline"
    s = {}
    try:
        s = json.loads((plug / "settings.json").read_text(encoding="utf-8"))
    except Exception:
        pass
    return {"found": True, "root": str(root), "installed": (plug / "py" / "__init__.py").is_file(), "bulk": s.get("bulk", ""),
            "online": bool(s.get("online_fallback", True)), "indexed": (plug / "data" / "index.json").is_file()}


def install(path, bulk, online=True):
    root = find_proxyshop(path)
    if not root:
        raise ValueError("That is not the Proxyshop folder - pick the folder with Proxyshop.exe in it.")
    plug = root / "plugins" / "NightvaultOffline"
    for rel, text in FILES.items():
        f = plug / rel
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_text(text, encoding="utf-8")
    (plug / "data").mkdir(exist_ok=True)
    (plug / "settings.json").write_text(json.dumps({"bulk": bulk or "", "online_fallback": bool(online)}, indent=2), encoding="utf-8")
    return str(plug)
